import "server-only";
import type { StyleSlug } from "@/lib/catalog";

/**
 * One swatch per style, cut from our own sample: two faceless crops (the ground with the coat's
 * edge, and the chest band) side by side. It shows the medium, marks, palette and ground without
 * showing a face, so the model cannot borrow the sample dog's markings or eyes. JPEG, base64. Regenerate with the
 * snippet in docs/art-direction.md when a sample changes.
 */
const REFS: Record<StyleSlug, string> = {
  "modern":
    "",
  "modern-sage":
    "",
  "watercolor":
    "",
  "fine-line":
    "",
  "pastel":
    "",
  "modern-oil":
    "",
  "charcoal":
    "",
};

/** The style reference image for a style, or null if there is none. */
export function styleReference(style: StyleSlug): { bytes: Buffer; mime: string } | null {
  const b64 = REFS[style];
  return b64 ? { bytes: Buffer.from(b64, "base64"), mime: "image/jpeg" } : null;
}
